for(let minute=0;minute<=15;minute++){
 await sleep(Math.max(0,start+minute*60000-performance.now()));
 const fps=await new Promise(resolve=>{let frames=0;const begin=performance.now();const tick=now=>{frames++;if(now-begin>=5000)resolve(frames*1000/(now-begin));else requestAnimationFrame(tick);};requestAnimationFrame(tick);});
 const keys=window.log.getFieldKeys();
 const counts=keys.map(k=>window.log.getField(k)?.getTimestampCount()??0);
