observer.disconnect();
return {mode,fields,selected:window.tabs.getSelectedTab(),tabs:window.tabs.saveState(),series};

const sleep=ms=>new Promise(r=>setTimeout(r,ms));
await sleep(3000);
const fields=['/vehicles/mur27/powertrain/inverter/motor_speed','/vehicles/mur27/dynamics/vehicle_speed','/vehicles/mur27/dynamics/wheel_speed_fl','/vehicles/mur27/dynamics/wheel_speed_fr','/vehicles/mur27/dynamics/yaw_rate','/vehicles/mur27/gps/latitude','/vehicles/mur27/gps/longitude','/vehicles/mur27/gps/ground_speed'];
const sources=fields.map(logKey=>({logKey,logType:'Number',type:'tile',visible:true,options:{showInGraph:'false'}}));
window.tabs.restoreState({selected:0,tabs:[{type:15,title:'Toggle isolation',controllerUUID:'isolate',controller:{sources,limits:{}},renderer:null,controlsHeight:240}]});
const tab=window.tabs.tabList[0];
let tileRefreshes=0,graphRestores=0;
const refresh=tab.controller.sourceList.refresh.bind(tab.controller.sourceList);
tab.controller.sourceList.refresh=(...args)=>{tileRefreshes++;return refresh(...args);};
const restore=tab.controller.graphController.restoreState.bind(tab.controller.graphController);
tab.controller.graphController.restoreState=(...args)=>{graphRestores++;return restore(...args);};
const edge=window.selection.getCurrentLiveTime();
for(let i=0;i<45000;i++)for(let f=0;f<fields.length;f++)window.log.putNumber(fields[f],edge-900+i/50,f===5?-37.7+Math.sin(i/1000)*0.0001:f===6?144.6+Math.cos(i/1000)*0.0001:100+Math.sin(i/30+f)*20);
window.selection.setTimelineRange([edge-900,edge],true);
let bandCalls=0,bandMs=0,bandMaxMs=0;
const originalBands=window.tabs.timeline.bandSupplier;
window.tabs.timeline.bandSupplier=()=>{const start=performance.now();const r=originalBands();const ms=performance.now()-start;bandCalls++;bandMs+=ms;bandMaxMs=Math.max(bandMaxMs,ms);return r;};
const result=[];
for(const enabled of [false,true,false]){
 if(enabled!==false || result.length) [...document.querySelectorAll('.show-in-graph')].slice(0,4).forEach(button=>button.click());
 const before={tileRefreshes,graphRestores};
 let tasks=0,longest=0;const observer=new PerformanceObserver(list=>list.getEntries().forEach(e=>{tasks++;longest=Math.max(longest,e.duration);}));observer.observe({type:'longtask'});
 for(let second=0;second<=10;second+=10){
  if(second)await sleep(10000);else await sleep(1000);
  const cmd=tab.controller.getCommand();
  let nodes=0;const walker=document.createTreeWalker(document,NodeFilter.SHOW_ALL);while(walker.nextNode())nodes++;
  result.push({enabled,second,bandCalls,bandMs,bandMaxMs,tasks,longest,heapMB:Math.round(performance.memory.usedJSHeapSize/1048576*10)/10,domElements:document.getElementsByTagName('*').length,allDomNodes:nodes,tiles:document.querySelectorAll('.trackside-tile').length,graph:!!cmd.graph,graphBytes:JSON.stringify(cmd.graph).length,fields:window.log.getFieldCount(),samples:window.log.getFieldKeys().reduce((n,k)=>n+(window.log.getField(k)?.getTimestampCount()??0),0),tileRefreshes:tileRefreshes-before.tileRefreshes,graphRestores:graphRestores-before.graphRestores,alertElements:document.querySelectorAll('.trackside-alerts').length});
 }
 observer.disconnect();
}
window.tabs.timeline.bandSupplier=()=>[];
let tasks=0,longest=0;const observer=new PerformanceObserver(list=>list.getEntries().forEach(e=>{tasks++;longest=Math.max(longest,e.duration);}));observer.observe({type:'longtask'});
const fps=await new Promise(resolve=>{let n=0;const start=performance.now();function tick(t){n++;if(t-start>=10000)resolve(n*1000/(t-start));else requestAnimationFrame(tick);}requestAnimationFrame(tick);});
observer.disconnect();result.push({phase:'lap-bands-disabled',tasks,longest,fps,bandCalls,bandMs,bandMaxMs});
return result;
